async function executeQuery<T>(query: string, params: any[]): Promise<T[]> {
  try {
    const rows = await db.query(query, params);
    return rows as T[];
  } catch (error) {
    throw new Error(`Database query failed: ${error instanceof Error ? error.message : 'Unknown error'}`);
  }
}

export async function searchTodos(keyword: string): Promise<Todo[]> {
  if (!keyword || keyword.trim().length === 0) return [];
  const query = 'SELECT * FROM todos WHERE title LIKE $1 OR description LIKE $1 ORDER BY created_at DESC';
  return executeQuery<Todo>(query, [`%${keyword}%`]);
}

